{"rob": "robolang 1.3;

task transfer(robot r, object o, location src, location dst, region fence) {
    pre { object_at o src; robot_ready r; region_clear fence; }
    goal { object_at o dst; }
    plan {
        move r to src;
        grasp r o;
        move r to dst;
        place r o at dst;
    }
}
